"""Check both public APIs in the prior bounded pure-Python runner."""

import ast
import hashlib
import tempfile
from pathlib import Path

from lessons.e11_task_completion.verify import probe


class ContractViolation(ValueError):
    pass


def quote_source(core, checkout):
    """Bind the permitted import in-memory, then let the old runner validate all ASTs."""
    tree = ast.parse(checkout)
    imports = [n for n in tree.body if isinstance(n, (ast.Import, ast.ImportFrom))]
    if len(imports) != 1:
        raise ValueError("checkout needs exactly the declared shipping import")
    imported = imports[0]
    if (
        not isinstance(imported, ast.ImportFrom)
        or imported.module != "shipping"
        or imported.level != 0
        or [(n.name, n.asname) for n in imported.names] != [("shipping_fee", None)]
    ):
        raise ValueError("Only from shipping import shipping_fee is supported")
    tree.body.remove(imported)
    functions = [n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == "quote"]
    if len(functions) != 1:
        raise ContractViolation("One quote function is required")
    args = functions[0].args
    if (
        [a.arg for a in args.args] != ["weight_grams", "expedited"]
        or args.posonlyargs
        or args.kwonlyargs
        or args.vararg
        or args.kwarg
        or len(args.defaults) != 1
        or not isinstance(args.defaults[0], ast.Constant)
        or args.defaults[0].value is not False
    ):
        raise ContractViolation("The public quote signature changed")
    if not any(
        isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id == "shipping_fee"
        for n in ast.walk(functions[0])
    ):
        raise ContractViolation("quote must call the core shipping_fee")
    core_tree = ast.parse(core)
    for n in ast.walk(core_tree):
        if isinstance(n, ast.FunctionDef) and n.name == "shipping_fee":
            n.name = "_core_shipping_fee"
        elif isinstance(n, ast.Name) and n.id == "shipping_fee":
            n.id = "_core_shipping_fee"
    for n in ast.walk(tree):
        if isinstance(n, ast.Name) and n.id == "shipping_fee":
            n.id = "_core_shipping_fee"
    functions[0].name = "shipping_fee"
    return ast.unparse(ast.Module(body=[*core_tree.body, *tree.body], type_ignores=[])) + "\n"


def files_at(workspace, names):
    root = Path(workspace).resolve()
    result = {}
    for name in names:
        path = root / name
        if not path.resolve().is_relative_to(root):
            raise ValueError("Artifact escapes workspace")
        result[name] = path.read_text() if path.is_file() else None
    return result


def verify(workspace, case, criteria):
    artifacts = files_at(workspace, case["files"])
    hashes = {
        name: hashlib.sha256(text.encode()).hexdigest() if text is not None else None
        for name, text in artifacts.items()
    }
    protected = {
        name: artifacts[name] == case["files"][name]
        for name in ("test_shipping.py", "test_checkout.py")
    }
    core = probe(Path(workspace), case, criteria)
    if artifacts["checkout.py"] is None or artifacts["shipping.py"] is None:
        return {
            "status": "scored",
            "passed": False,
            "checks": {"implementation_files_exist": False},
            "artifact_hashes": hashes,
            "core": core,
        }
    try:
        combined = quote_source(artifacts["shipping.py"], artifacts["checkout.py"])
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            (root / "shipping.py").write_text(combined)
            (root / "test_shipping.py").write_text(artifacts["test_shipping.py"] or "")
            entry = probe(root, case, criteria)
    except ContractViolation as error:
        return {
            "status": "scored",
            "passed": False,
            "checks": {"quote_contract": False},
            "error": str(error),
            "core": core,
            "artifact_hashes": hashes,
        }
    except (ValueError, TypeError, SyntaxError) as error:
        return {
            "status": "unscored",
            "passed": None,
            "error": str(error),
            "core": core,
            "artifact_hashes": hashes,
        }
    checks = {
        **protected,
        "core_behavior": core["passed"] is True,
        "quote_behavior": entry["passed"] is True,
    }
    return {
        "status": "scored" if core["status"] == entry["status"] == "scored" else "unscored",
        "passed": all(checks.values()) if core["status"] == entry["status"] == "scored" else None,
        "checks": checks,
        "core": core,
        "quote_via_bound_core": entry,
        "quote_binding": "declared import removed and names bound for the restricted runner; not a new Agent execution",
        "artifact_hashes": hashes,
    }

lessons/e13_planning/state.py:
"""Explicit plans, dependency transitions, and one-consumer file mailboxes."""

import copy
import json
import re
import threading
import uuid
from pathlib import Path

STATES = {"pending", "in_progress", "completed"}


class TodoManager:
    def __init__(self):
        self.items = []
        self.rounds_without_update = 0

    def update(self, items):
        if not isinstance(items, list) or not 1 <= len(items) <= 20:
            raise ValueError("A plan must contain 1..20 items")
        for item in items:
            if (
                not isinstance(item, dict)
                or set(item) != {"content", "status"}
                or not isinstance(item["content"], str)
                or not item["content"].strip()
                or not isinstance(item["status"], str)
                or item["status"] not in STATES
            ):
                raise ValueError("Each item needs nonempty content and a valid status")
        if sum(i["status"] == "in_progress" for i in items) > 1:
            raise ValueError("Only one todo may be in_progress")
        self.items = copy.deepcopy(items)
        self.rounds_without_update = 0
        return self.items

    def reminder(self, tool_names):
        self.rounds_without_update = (
            0 if "todo_write" in tool_names else self.rounds_without_update + 1
        )
        if self.rounds_without_update < 3:
            return None
        self.rounds_without_update = 0
        return "Plan reminder: update your explicit todos using actual progress."


class TaskStore:
    def __init__(self, workspace):
        self.workspace = Path(workspace).resolve()
        self.root = self.workspace / ".tasks"
        if self.root.is_symlink():
            raise ValueError("Task directory cannot be a symlink")
        self.root.mkdir(exist_ok=True)
        self.lock = threading.RLock()
        self.events = []

    def path(self, task_id):
        if self.root.is_symlink() or self.root.resolve().parent != self.workspace:
            raise ValueError("Task directory escapes workspace")
        if not isinstance(task_id, str) or not re.fullmatch(r"task_[a-f0-9]{8}", task_id):
            raise ValueError("Invalid task ID")
        path = self.root / (task_id + ".json")
        if path.is_symlink():
            raise ValueError("Task record cannot be a symlink")
        return path

    def load(self, task_id):
        task = json.loads(self.path(task_id).read_text())
        if (
            task["id"] != task_id
            or not isinstance(task["status"], str)
            or task["status"] not in STATES
            or not isinstance(task["blocked_by"], list)
            or not all(isinstance(d, str) for d in task["blocked_by"])
            or (task["status"] != "pending" and not isinstance(task["owner"], str))
        ):
            raise ValueError("Invalid persisted task")
        return task

    def list(self):
        with self.lock:
            return [self.load(p.stem) for p in sorted(self.root.glob("task_*.json"))]

    def save(self, task, action, actor):
        path = self.path(task["id"])
        temporary = path.with_suffix(".tmp")
        if temporary.is_symlink():
            raise ValueError("Temporary task record cannot be a symlink")
        temporary.write_text(json.dumps(task, ensure_ascii=False, indent=2) + "\n")
        temporary.replace(path)
        self.events.append(
            {
                "sequence": len(self.events),
                "action": action,
                "actor": actor,
                "task": copy.deepcopy(task),
            }
        )
        return copy.deepcopy(task)

    def create(self, subject, description=""):
        if not isinstance(subject, str) or not subject.strip() or not isinstance(description, str):
            raise ValueError(
                "Task subject and description must be strings; subject cannot be blank"
            )
        with self.lock:
            task = {
                "id": "task_" + uuid.uuid4().hex[:8],
                "subject": subject,
                "description": description,
                "status": "pending",
                "owner": None,
                "blocked_by": [],
            }
            if self.path(task["id"]).exists():
                raise FileExistsError("Task ID collision")
            return self.save(task, "create", "lead")

    def add_dependencies(self, task_id, dependencies):
        with self.lock:
            task = self.load(task_id)
            if task["status"] != "pending" or task["owner"] is not None:
                raise ValueError("Only an unowned pending task can change dependencies")
            if not isinstance(dependencies, list) or not all(
                isinstance(d, str) for d in dependencies
            ):
                raise ValueError("Dependencies must be a list of task IDs")
            for dependency in dependencies:
                pending, seen = [dependency], set()
                while pending:
                    current = pending.pop()
                    if current == task_id:
                        raise ValueError("Dependency cycle")
                    if current not in seen:
                        seen.add(current)
                        pending.extend(self.load(current)["blocked_by"])
            task["blocked_by"] = list(dict.fromkeys([*task["blocked_by"], *dependencies]))
            return self.save(task, "add_dependencies", "lead")

    def claim(self, task_id, owner):
        if not isinstance(owner, str) or not re.fullmatch(r"[a-z][a-z0-9_-]{0,31}", owner):
            raise ValueError("Invalid owner")
        with self.lock:
            task = self.load(task_id)
            if task["status"] != "pending" or task["owner"] is not None:
                raise ValueError("Task is already claimed or completed")
            if any(t["owner"] == owner and t["status"] == "in_progress" for t in self.list()):
                raise ValueError("Owner already has an active task")
            if any(self.load(d)["status"] != "completed" for d in task["blocked_by"]):
                raise ValueError("Dependencies are incomplete")
            task.update(owner=owner, status="in_progress")
            return self.save(task, "claim", owner)

    def complete(self, task_id, owner):
        with self.lock:
            task = self.load(task_id)
            if task["status"] != "in_progress" or task["owner"] != owner:
                raise ValueError("Only the active owner may complete a task")
            task["status"] = "completed"
            return self.save(task, "complete_claim", owner)


class MessageBus:
    def __init__(self, workspace):
        self.workspace = Path(workspace).resolve()
        self.root = self.workspace / ".mailboxes"
        if self.root.is_symlink():
            raise ValueError("Mailbox directory cannot be a symlink")
        self.root.mkdir(exist_ok=True)
        self.lock = threading.RLock()
        self.events = []

    def path(self, name):
        if self.root.is_symlink() or self.root.resolve().parent != self.workspace:
            raise ValueError("Mailbox directory escapes workspace")
        if not isinstance(name, str) or not re.fullmatch(r"[a-z][a-z0-9_-]{0,31}", name):
            raise ValueError("Invalid mailbox name")
        path = self.root / (name + ".jsonl")
        if path.is_symlink():
            raise ValueError("Mailbox cannot be a symlink")
        return path

    def send(self, sender, recipient, task_id, content, status):
        with self.lock:
            self.path(sender)
            row = {
                "sender": sender,
                "recipient": recipient,
                "task_id": task_id,
                "content": content,
                "status": status,
            }
            with self.path(recipient).open("a") as file:
                file.write(json.dumps(row, ensure_ascii=False) + "\n")
            self.events.append(copy.deepcopy(row))
            return row

    def consume(self, recipient):
        with self.lock:
            path = self.path(recipient)
            if not path.exists():
                return []
            rows = [json.loads(line) for line in path.read_text().splitlines()]
            path.unlink()
            return rows

